// nouPix · js/builtins.js
// The built-in content library: ISF shaders and their categories, as data (BUILTINS).

const BUILTINS = [{"id": "rainbow", "name": "Rainbow", "code": "/*{\"DESCRIPTION\":\"Scrolling rainbow\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\",\"ambient\",\"gradient\",\"flow\",\"rainbow\",\"scroll\",\"colorful\"],\"INPUTS\":[\n{\"NAME\":\"mode\",\"LABEL\":\"Shape\",\"TYPE\":\"long\",\"VALUES\":[0,1,2],\"LABELS\":[\"Linear\",\"Radial\",\"Angular\"],\"DEFAULT\":0},\n{\"NAME\":\"palette\",\"LABEL\":\"Colors\",\"TYPE\":\"long\",\"VALUES\":[0,1],\"LABELS\":[\"Rainbow\",\"Color A to B\"],\"DEFAULT\":0},\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.15,0.45,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.15,0.45,1,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-2,\"MAX\":2,\"DEFAULT\":0.25},\n{\"NAME\":\"scale\",\"LABEL\":\"Repeat (0 = colour cycle)\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":6,\"DEFAULT\":1},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0},\n{\"NAME\":\"saturation\",\"LABEL\":\"Saturation\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1}]}*/\nvec3 hsv(float h, float s) { vec3 p = abs(fract(h + vec3(1.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0); return mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), s); }\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float v;\n  if (mode == 0) v = dot(p, vec2(cos(a), sin(a))) * scale;\n  else if (mode == 1) v = length(p) * scale;\n  else v = atan(p.y, p.x) / 6.2831853 * floor(scale + 0.5) + a / 6.2831853;\n  // Rainbow: every hue in turn; Color A to B: from one to the other and back, as pale as the saturation says\n  if (palette == 0) gl_FragColor = vec4(hsv(v - TIME * speed, saturation), 1.0);\n  else gl_FragColor = vec4(mix(vec3(1.0), mix(colorA.rgb, colorB.rgb, 0.5 - 0.5 * cos(6.2831853 * (v - TIME * speed))), saturation), 1.0);\n}\n"}, {"id": "plasma", "name": "Plasma", "code": "/*{\"DESCRIPTION\":\"Classic plasma\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\",\"ambient\",\"organic\",\"drift\",\"rainbow\",\"psychedelic\",\"colorful\"],\"INPUTS\":[\n{\"NAME\":\"palette\",\"LABEL\":\"Colors\",\"TYPE\":\"long\",\"VALUES\":[0,1],\"LABELS\":[\"Rainbow\",\"Color A to B\"],\"DEFAULT\":0},\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.1,0.55,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.1,0.7,1,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":3,\"DEFAULT\":0.5},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":12,\"DEFAULT\":4},\n{\"NAME\":\"hue\",\"LABEL\":\"Hue offset\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0},\n{\"NAME\":\"range\",\"LABEL\":\"Hue range\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1},\n{\"NAME\":\"saturation\",\"LABEL\":\"Saturation\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1}]}*/\nvec3 hsv(float h, float s) { vec3 p = abs(fract(h + vec3(1.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0); return mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), s); }\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0) * scale;\n  float t = TIME * speed;\n  float v = sin(p.x + t) + sin(p.y * 0.8 - t * 1.3) + sin((p.x + p.y) * 0.7 + t * 0.7) + sin(length(p + vec2(sin(t * 0.5), cos(t * 0.4)) * 2.0) * 1.5);\n  // Rainbow: hues around the hue offset; Color A to B: between the two, as pale as the saturation says\n  if (palette == 0) gl_FragColor = vec4(hsv(hue + v * 0.125 * range, saturation), 1.0);\n  else gl_FragColor = vec4(mix(vec3(1.0), mix(colorA.rgb, colorB.rgb, 0.5 - 0.5 * cos(6.2831853 * (hue + v * 0.125 * range))), saturation), 1.0);\n}\n"}, {"id": "noise", "name": "Noise", "code": "/*{\"DESCRIPTION\":\"Drifting fractal noise between two colors\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"ambient\",\"organic\",\"drift\",\"clouds\",\"fractal\",\"smoke\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.35,0,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.05,0,0.25,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":3,\"DEFAULT\":0.4},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":20,\"DEFAULT\":4},\n{\"NAME\":\"contrast\",\"LABEL\":\"Contrast\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":4,\"DEFAULT\":1.5}]}*/\nfloat hash(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }\nfloat noise(vec3 p) {\n  vec3 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(mix(hash(i), hash(i + vec3(1,0,0)), f.x), mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),\n             mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x), mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y), f.z);\n}\nvoid main() {\n  vec3 p = vec3((isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0) * scale, TIME * speed);\n  float n = noise(p) * 0.55 + noise(p * 2.1 + 3.7) * 0.3 + noise(p * 4.3 + 7.1) * 0.15;\n  n = clamp((n - 0.5) * contrast + 0.5, 0.0, 1.0);\n  gl_FragColor = vec4(mix(colorB.rgb, colorA.rgb, n), 1.0);\n}\n"}, {"id": "aurora", "name": "Aurora", "code": "/*{\"DESCRIPTION\":\"Slow curtains of light\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"organic\",\"drift\",\"northern lights\",\"curtains\",\"sky\",\"nature\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Low color\",\"TYPE\":\"color\",\"DEFAULT\":[0.1,1,0.55,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"High color\",\"TYPE\":\"color\",\"DEFAULT\":[0.55,0.2,1,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":2,\"DEFAULT\":0.3},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.3,\"MAX\":4,\"DEFAULT\":1},\n{\"NAME\":\"brightness\",\"LABEL\":\"Brightness\",\"TYPE\":\"float\",\"MIN\":0.2,\"MAX\":2,\"DEFAULT\":1.1}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453); }\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);\n}\nvoid main() {\n  vec2 q = isf_FragNormCoord * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0) / scale;\n  float t = TIME * speed;\n  float bend = sin(q.x * 1.7 + t * 0.7) * 0.12 + sin(q.x * 3.1 - t * 0.5) * 0.06 + noise(vec2(q.x * 2.0, t * 0.3)) * 0.15;\n  float y = isf_FragNormCoord.y - 0.35 - bend;\n  float band = smoothstep(-0.12, 0.02, y) * exp(-max(y, 0.0) * 3.5);\n  float rays = 0.35 + 0.65 * noise(vec2(q.x * 9.0 + bend * 6.0, t * 0.8));\n  float m = band * rays * brightness;\n  vec3 c = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 0.45, y));\n  gl_FragColor = vec4(clamp(c * m, 0.0, 1.0), 1.0);\n}\n"}, {"id": "water", "name": "Water", "code": "/*{\"DESCRIPTION\":\"Light rippling like the bottom of a pool\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"organic\",\"drift\",\"pool\",\"caustics\",\"sea\",\"nature\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Deep\",\"TYPE\":\"color\",\"DEFAULT\":[0,0.12,0.35,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Light\",\"TYPE\":\"color\",\"DEFAULT\":[0.55,0.95,1,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":2,\"DEFAULT\":0.4},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":10,\"DEFAULT\":3},\n{\"NAME\":\"sharpness\",\"LABEL\":\"Sharpness\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":12,\"DEFAULT\":5}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);\n}\nfloat web(vec2 p, float t) {\n  vec2 w = vec2(noise(p + vec2(t, 0.0)), noise(p + vec2(5.2, t * 1.3)));\n  float n = noise(p * 1.7 + w * 2.0 - vec2(0.0, t * 0.6));\n  return pow(1.0 - abs(sin(n * 9.0)), sharpness);\n}\nvoid main() {\n  vec2 p = isf_FragNormCoord * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0) * scale;\n  float t = TIME * speed;\n  float v = web(p, t) * 0.65 + web(p * 1.6 + 3.1, t * 1.2) * 0.45;\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, clamp(v, 0.0, 1.0)), 1.0);\n}\n"}, {"id": "fire", "name": "Fire", "code": "/*{\"DESCRIPTION\":\"Flames rising from the bottom edge\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\",\"ambient\",\"organic\",\"flow\",\"flames\",\"warm\",\"nature\"],\"INPUTS\":[\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":3,\"DEFAULT\":1},\n{\"NAME\":\"height\",\"LABEL\":\"Flame height\",\"TYPE\":\"float\",\"MIN\":0.1,\"MAX\":1.5,\"DEFAULT\":0.75},\n{\"NAME\":\"detail\",\"LABEL\":\"Detail\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":12,\"DEFAULT\":4},\n{\"NAME\":\"hue\",\"LABEL\":\"Hue shift\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);\n}\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * noise(p); p = p * 2.03 + 11.7; a *= 0.5; } return v; }\nvec3 hueShift(vec3 c, float a) { const vec3 k = vec3(0.57735); float ca = cos(a); return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca); }\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = vec2(uv.x * RENDERSIZE.x / RENDERSIZE.y, uv.y) * detail;\n  float t = TIME * speed;\n  float n = fbm(p + vec2(0.0, -t * 1.6));\n  n = fbm(p + vec2(n * 1.3, -t * 2.2));\n  float heat = clamp(1.0 - uv.y / height + (n - 0.5) * 1.5, 0.0, 1.0);\n  heat = heat * heat * (0.55 + 0.9 * n);\n  vec3 c = clamp(vec3(heat * 1.9, heat * heat * 1.5, pow(heat, 4.0) * 1.2), 0.0, 1.0);\n  gl_FragColor = vec4(clamp(hueShift(c, hue * 6.2831853), 0.0, 1.0), 1.0);\n}\n"}, {"id": "lava", "name": "Lava lamp", "code": "/*{\"DESCRIPTION\":\"Soft blobs drifting and merging, like a lava lamp\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"ambient\",\"organic\",\"drift\",\"blobs\",\"warm\",\"retro\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Blob color\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.3,0.05,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.08,0,0.12,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Blobs\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":8,\"DEFAULT\":5},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.03,\"MAX\":0.4,\"DEFAULT\":0.13},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":2,\"DEFAULT\":0.4},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.3}]}*/\nvoid main() {\n  vec2 asp = vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 q = isf_FragNormCoord * asp;\n  float t = TIME * speed;\n  float f = 0.0;\n  for (int i = 0; i < 8; i++) {\n    float fi = float(i);\n    if (fi >= floor(count + 0.5)) break;\n    vec2 c = vec2(0.5 + 0.42 * sin(t * (0.31 + 0.07 * fi) + fi * 1.7), 0.5 + 0.42 * sin(t * (0.23 + 0.09 * fi) + fi * 2.9)) * asp;\n    vec2 d = q - c;\n    f += size * size / max(dot(d, d), 1e-5);\n  }\n  float s = softness * 0.8 + 0.02;\n  float m = smoothstep(1.0 - s, 1.0 + s, f);\n  gl_FragColor = vec4(mix(colorB.rgb, colorA.rgb, m), 1.0);\n}\n"}, {"id": "bars", "name": "Bars", "code": "/*{\"DESCRIPTION\":\"Moving bars\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\",\"show\",\"lines\",\"chase\",\"stripes\",\"scroll\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Bar color\",\"TYPE\":\"color\",\"DEFAULT\":[1,1,1,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0,0,0,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Bars\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":24,\"DEFAULT\":4},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.02,\"MAX\":1,\"DEFAULT\":0.35},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.2},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-3,\"MAX\":3,\"DEFAULT\":0.5},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float x = dot(p, vec2(cos(a), sin(a))) * count - TIME * speed;\n  float d = abs(fract(x) - 0.5) * 2.0;\n  float s = softness * 0.5 + 0.001;\n  float m = 1.0 - smoothstep(width - s, width + s, d);\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, m), 1.0);\n}\n"}, {"id": "comet", "name": "Comet chase", "code": "/*{\"DESCRIPTION\":\"Comets with fading tails, along a direction, outwards from a centre, or around it\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\",\"show\",\"lines\",\"chase\",\"tails\",\"trails\",\"runner\"],\"INPUTS\":[\n{\"NAME\":\"mode\",\"LABEL\":\"Path\",\"TYPE\":\"long\",\"VALUES\":[0,1,2],\"LABELS\":[\"Straight\",\"Outwards\",\"Around\"],\"DEFAULT\":0},\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.55,0.15,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Comets\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":12,\"DEFAULT\":3},\n{\"NAME\":\"tail\",\"LABEL\":\"Tail\",\"TYPE\":\"float\",\"MIN\":0.02,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-3,\"MAX\":3,\"DEFAULT\":0.5},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0},\n{\"NAME\":\"centerX\",\"LABEL\":\"Centre X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Centre Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - vec2(centerX, 1.0 - centerY)) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float x;\n  if (mode == 0) x = dot(p, vec2(cos(a), sin(a))) * count * 0.5;\n  else if (mode == 1) x = length(p) * count;\n  else x = (atan(p.x, p.y) - a) / 6.2831853 * floor(count + 0.5);\n  float d = fract((TIME * speed - x) * (speed < 0.0 ? -1.0 : 1.0));\n  float m = pow(clamp(1.0 - d / tail, 0.0, 1.0), 2.5);\n  gl_FragColor = vec4(color.rgb * m, 1.0);\n}\n"}, {"id": "wipe", "name": "Color wipe", "code": "/*{\"DESCRIPTION\":\"Two colours wiping over each other in turn\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"fill\",\"flow\",\"transition\",\"two colours\"],\"INPUTS\":[\n{\"NAME\":\"mode\",\"LABEL\":\"Wipe\",\"TYPE\":\"long\",\"VALUES\":[0,1,2],\"LABELS\":[\"Straight\",\"From centre\",\"Clock\"],\"DEFAULT\":0},\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.1,0.6,1,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.2,0.5,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Wipes / s\",\"TYPE\":\"float\",\"MIN\":-2,\"MAX\":2,\"DEFAULT\":0.4},\n{\"NAME\":\"hold\",\"LABEL\":\"Hold\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":0.9,\"DEFAULT\":0.3},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 asp = vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 q = (isf_FragNormCoord - 0.5) * asp;\n  float a = radians(angle);\n  float x;\n  if (mode == 0) { vec2 d = vec2(cos(a), sin(a)); x = dot(q, d) / (abs(d.x) * asp.x + abs(d.y) * asp.y) + 0.5; }\n  else if (mode == 1) x = length(q) / length(0.5 * asp);\n  else x = fract((atan(q.x, q.y) - a) / 6.2831853);\n  if (speed < 0.0) x = 1.0 - x;\n  float t = TIME * abs(speed);\n  float k = mod(floor(t), 2.0);\n  float f = clamp(fract(t) / (1.0 - hold), 0.0, 1.0);\n  float s = softness * 0.25 + 0.001;\n  float m = 1.0 - smoothstep(-s, s, x - f * (1.0 + 2.0 * s) + s);\n  vec3 newC = k < 1.0 ? colorA.rgb : colorB.rgb, oldC = k < 1.0 ? colorB.rgb : colorA.rgb;\n  gl_FragColor = vec4(mix(oldC, newC, m), 1.0);\n}\n"}, {"id": "pulse", "name": "Pulse rings", "code": "/*{\"DESCRIPTION\":\"Rings expanding from a centre point\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\",\"show\",\"radial\",\"flow\",\"rings\",\"ripple\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Ring color\",\"TYPE\":\"color\",\"DEFAULT\":[0.2,0.8,1,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0,0,0,1]},\n{\"NAME\":\"frequency\",\"LABEL\":\"Rings\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":20,\"DEFAULT\":3},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-3,\"MAX\":3,\"DEFAULT\":0.6},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.02,\"MAX\":1,\"DEFAULT\":0.3},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"centerX\",\"LABEL\":\"Centre X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Centre Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nvoid main() {\n  vec2 asp = vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 p = (isf_FragNormCoord - vec2(centerX, 1.0 - centerY)) * asp;\n  float x = length(p) * frequency - TIME * speed;\n  float d = abs(fract(x) - 0.5) * 2.0;\n  float s = softness * 0.5 + 0.001;\n  float m = 1.0 - smoothstep(width - s, width + s, d);\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, m), 1.0);\n}\n"}, {"id": "sweep", "name": "Radar sweep", "code": "/*{\"DESCRIPTION\":\"Rotating radar sweep with a fading tail\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\",\"show\",\"radial\",\"chase\",\"radar\",\"rotate\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[0.3,1,0.5,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Turns / s\",\"TYPE\":\"float\",\"MIN\":-2,\"MAX\":2,\"DEFAULT\":0.3},\n{\"NAME\":\"tail\",\"LABEL\":\"Tail\",\"TYPE\":\"float\",\"MIN\":0.02,\"MAX\":1,\"DEFAULT\":0.35},\n{\"NAME\":\"arms\",\"LABEL\":\"Arms\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":8,\"DEFAULT\":1},\n{\"NAME\":\"centerX\",\"LABEL\":\"Centre X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Centre Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - vec2(centerX, 1.0 - centerY)) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = atan(p.x, p.y) / 6.2831853;\n  float k = floor(arms + 0.5);\n  float x = fract((a - TIME * speed) * k);\n  if (speed < 0.0) x = 1.0 - x;\n  float m = pow(clamp(1.0 - x / tail, 0.0, 1.0), 2.0);\n  gl_FragColor = vec4(color.rgb * m, 1.0);\n}\n"}, {"id": "spiral", "name": "Spiral", "code": "/*{\"DESCRIPTION\":\"Rotating spiral arms\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"radial\",\"flow\",\"rotate\",\"hypnotic\",\"psychedelic\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Arm color\",\"TYPE\":\"color\",\"DEFAULT\":[0.2,0.9,1,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0,0,0,1]},\n{\"NAME\":\"rainbow\",\"LABEL\":\"Rainbow arms\",\"TYPE\":\"bool\",\"DEFAULT\":false},\n{\"NAME\":\"arms\",\"LABEL\":\"Arms\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":12,\"DEFAULT\":3},\n{\"NAME\":\"twist\",\"LABEL\":\"Twist\",\"TYPE\":\"float\",\"MIN\":-8,\"MAX\":8,\"DEFAULT\":2.5},\n{\"NAME\":\"speed\",\"LABEL\":\"Turns / s\",\"TYPE\":\"float\",\"MIN\":-2,\"MAX\":2,\"DEFAULT\":0.2},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"centerX\",\"LABEL\":\"Centre X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Centre Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nvec3 hsv(float h) { return clamp(abs(fract(h + vec3(1.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0); }\nvoid main() {\n  vec2 q = (isf_FragNormCoord - vec2(centerX, 1.0 - centerY)) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float th = atan(q.y, q.x) / 6.2831853;\n  float k = floor(arms + 0.5);\n  float x = (th + length(q) * twist * 0.5 - TIME * speed) * k;\n  float d = abs(fract(x) - 0.5) * 2.0;\n  float m = 1.0 - smoothstep(width - 0.12, width + 0.12, d);\n  vec3 c = rainbow ? hsv(floor(x) / k + TIME * speed * 0.25) : color.rgb;\n  gl_FragColor = vec4(mix(background.rgb, c, m), 1.0);\n}\n"}, {"id": "rain", "name": "Rain", "code": "/*{\"DESCRIPTION\":\"Falling drops with fading trails, each column at its own speed\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"ambient\",\"particles\",\"flow\",\"drops\",\"water\",\"nature\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[0.55,0.8,1,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0,0,0,1]},\n{\"NAME\":\"cell\",\"LABEL\":\"Column width (px)\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":80,\"DEFAULT\":10},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":4,\"DEFAULT\":0.8},\n{\"NAME\":\"trail\",\"LABEL\":\"Trail\",\"TYPE\":\"float\",\"MIN\":0.02,\"MAX\":1,\"DEFAULT\":0.3},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nfloat hash(float n) { return fract(sin(n * 91.3458) * 47453.5453); }\nvoid main() {\n  vec2 c = (isf_FragNormCoord - 0.5) * RENDERSIZE;\n  float a = radians(angle);\n  c = vec2(c.x * cos(a) + c.y * sin(a), c.y * cos(a) - c.x * sin(a));\n  float col = floor(c.x / cell);\n  float spd = speed * (0.5 + hash(col));\n  float u = c.y / RENDERSIZE.y + TIME * spd + hash(col + 17.0);\n  float on = step(hash(col * 7.31 + floor(u) * 13.7), density);\n  float m = on * pow(clamp(1.0 - fract(u) / trail, 0.0, 1.0), 2.0);\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, m), 1.0);\n}\n"}, {"id": "twinkle", "name": "Twinkle", "code": "/*{\"DESCRIPTION\":\"Random twinkling cells\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"ambient\",\"particles\",\"drift\",\"stars\",\"sparkle\",\"glitter\",\"dots\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.85,0.6,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0,0,0,1]},\n{\"NAME\":\"cells\",\"LABEL\":\"Cell size (px)\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":80,\"DEFAULT\":10},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.25},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":4,\"DEFAULT\":1},\n{\"NAME\":\"decay\",\"LABEL\":\"Decay\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":8,\"DEFAULT\":3}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 c = floor(isf_FragNormCoord * RENDERSIZE / cells);\n  float h = hash(c);\n  float t = TIME * speed + h * 17.0;\n  float ph = fract(t);\n  float on = step(1.0 - density, hash(c + floor(t) * 1.618));\n  float m = on * pow(1.0 - ph, decay);\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, m), 1.0);\n}\n"}, {"id": "checker", "name": "Checkerboard", "code": "/*{\"DESCRIPTION\":\"Checkerboard that can flip and scroll\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"geometric\",\"flash\",\"squares\",\"grid\"],\"OLM_CLOCKS\":{\"flip\":{\"FROM\":\"rate\",\"WRAP\":1024},\"travel\":{\"FROM\":\"scroll\",\"WRAP\":1024}},\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1,1,1,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0,0,0,1]},\n{\"NAME\":\"size\",\"LABEL\":\"Square (px)\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":300,\"DEFAULT\":60},\n{\"NAME\":\"rate\",\"LABEL\":\"Flips / s\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":10,\"DEFAULT\":1},\n{\"NAME\":\"scroll\",\"LABEL\":\"Scroll\",\"TYPE\":\"float\",\"MIN\":-4,\"MAX\":4,\"DEFAULT\":0},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":90,\"DEFAULT\":0},\n{\"NAME\":\"flip\",\"TYPE\":\"float\",\"DEFAULT\":0},\n{\"NAME\":\"travel\",\"TYPE\":\"float\",\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 c = (isf_FragNormCoord - 0.5) * RENDERSIZE;\n  float a = radians(angle);\n  c = vec2(c.x * cos(a) + c.y * sin(a), c.y * cos(a) - c.x * sin(a));\n  c.x += travel * size;\n  vec2 k = floor(c / size);\n  float m = abs(mod(k.x + k.y, 2.0) - mod(floor(flip), 2.0));\n  gl_FragColor = vec4(mix(colorB.rgb, colorA.rgb, m), 1.0);\n}\n"}, {"id": "breathe", "name": "Breathe", "code": "/*{\"DESCRIPTION\":\"Slow breathing between two colours, optionally as a wave across the canvas\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"fill\",\"drift\",\"fade\",\"two colours\"],\"OLM_CLOCKS\":{\"breath\":{\"FROM\":\"rate\",\"SCALE\":0.016666666666666666,\"WRAP\":1024}},\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Bright\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.75,0.45,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Dim\",\"TYPE\":\"color\",\"DEFAULT\":[0.02,0.01,0,1]},\n{\"NAME\":\"rate\",\"LABEL\":\"Breaths / min\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":60,\"DEFAULT\":12},\n{\"NAME\":\"curve\",\"LABEL\":\"Curve\",\"TYPE\":\"float\",\"MIN\":0.3,\"MAX\":4,\"DEFAULT\":1.6},\n{\"NAME\":\"spread\",\"LABEL\":\"Wave\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":3,\"DEFAULT\":0},\n{\"NAME\":\"angle\",\"LABEL\":\"Wave angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0},\n{\"NAME\":\"breath\",\"TYPE\":\"float\",\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 q = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float ph = breath - dot(q, vec2(cos(a), sin(a))) * spread;\n  float v = pow(0.5 - 0.5 * cos(6.2831853 * ph), curve);\n  gl_FragColor = vec4(mix(colorB.rgb, colorA.rgb, v), 1.0);\n}\n"}, {"id": "strobe", "name": "Strobe", "code": "/*{\"DESCRIPTION\":\"Strobe\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"fill\",\"flash\",\"blinder\",\"white\"],\"OLM_CLOCKS\":{\"flash\":{\"FROM\":\"rate\",\"WRAP\":1024}},\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[1,1,1,1]},\n{\"NAME\":\"rate\",\"LABEL\":\"Rate (Hz)\",\"TYPE\":\"float\",\"MIN\":0.25,\"MAX\":20,\"DEFAULT\":4},\n{\"NAME\":\"duty\",\"LABEL\":\"On time\",\"TYPE\":\"float\",\"MIN\":0.02,\"MAX\":0.95,\"DEFAULT\":0.2},\n{\"NAME\":\"flash\",\"TYPE\":\"float\",\"DEFAULT\":0}]}*/\nvoid main() {\n  float on = step(fract(flash), duty);\n  gl_FragColor = vec4(color.rgb * on, 1.0);\n}\n"}, {"id": "drift", "name": "Color drift", "code": "/*{\"DESCRIPTION\":\"A very slow drift through the hues, with a gentle gradient across the canvas\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"fill\",\"drift\",\"hue\",\"colour cycle\",\"colorful\"],\"INPUTS\":[\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.08},\n{\"NAME\":\"spread\",\"LABEL\":\"Spread\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1.5,\"DEFAULT\":0.12},\n{\"NAME\":\"saturation\",\"LABEL\":\"Saturation\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.65},\n{\"NAME\":\"brightness\",\"LABEL\":\"Brightness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvec3 hsv(float h, float s, float v) { vec3 p = abs(fract(vec3(h) + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0); return v * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), s); }\nvoid main() {\n  vec2 q = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float h = TIME * speed * 0.05 + dot(q, vec2(cos(a), sin(a))) * spread;\n  gl_FragColor = vec4(hsv(h, saturation, brightness), 1.0);\n}\n"}, {"id": "clouds", "name": "Soft clouds", "code": "/*{\"DESCRIPTION\":\"Slow, soft clouds drifting over a sky\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"organic\",\"drift\",\"sky\",\"nature\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Sky\",\"TYPE\":\"color\",\"DEFAULT\":[0.02,0.06,0.22,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Clouds\",\"TYPE\":\"color\",\"DEFAULT\":[0.75,0.82,1,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":8,\"DEFAULT\":2.5},\n{\"NAME\":\"coverage\",\"LABEL\":\"Coverage\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":1,\"DEFAULT\":0.6}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y); }\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + vec2(17.0, 9.0); a *= 0.5; } return v; }\nvoid main() {\n  vec2 q = isf_FragNormCoord * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0) * scale;\n  float t = TIME * speed;\n  vec2 p = q + vec2(t * 0.4, t * 0.12);\n  float f = fbm(p + 0.8 * vec2(fbm(p + vec2(t * 0.07, 0.0)), fbm(p + vec2(5.2, 1.3 - t * 0.05))));\n  float m = smoothstep(1.0 - coverage - softness * 0.5, 1.0 - coverage + softness * 0.5, f);\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, m), 1.0);\n}\n"}, {"id": "horizon", "name": "Horizon", "code": "/*{\"DESCRIPTION\":\"A sky gradient with a warm glow at the horizon that slowly rises and sets\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"gradient\",\"drift\",\"sky\",\"sunrise\",\"sunset\",\"warm\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Sky\",\"TYPE\":\"color\",\"DEFAULT\":[0.03,0.05,0.25,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Glow\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.42,0.08,1]},\n{\"NAME\":\"colorC\",\"LABEL\":\"Ground\",\"TYPE\":\"color\",\"DEFAULT\":[0.08,0.02,0.0,1]},\n{\"NAME\":\"height\",\"LABEL\":\"Horizon\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.35},\n{\"NAME\":\"width\",\"LABEL\":\"Glow width\",\"TYPE\":\"float\",\"MIN\":0.02,\"MAX\":1,\"DEFAULT\":0.25},\n{\"NAME\":\"drift\",\"LABEL\":\"Rise and set\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":0.5,\"DEFAULT\":0.1},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.1}]}*/\nvoid main() {\n  float y = isf_FragNormCoord.y;\n  float hz = height + sin(TIME * speed) * drift;\n  vec3 sky = mix(colorB.rgb, colorA.rgb, smoothstep(hz, hz + width * 2.0, y));\n  vec3 col = y < hz ? mix(colorC.rgb, colorB.rgb, smoothstep(hz - width, hz, y)) : sky;\n  col += colorB.rgb * 0.6 * exp(-abs(y - hz) / max(width * 0.35, 0.001));\n  gl_FragColor = vec4(min(col, 1.0), 1.0);\n}\n"}, {"id": "stars", "name": "Starfield", "code": "/*{\"DESCRIPTION\":\"Scattered stars that softly twinkle on a night sky\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"ambient\",\"particles\",\"drift\",\"night\",\"twinkle\",\"sparkle\",\"sky\",\"dots\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Stars\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.95,0.85,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Sky\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.01,0.05,1]},\n{\"NAME\":\"cells\",\"LABEL\":\"Spacing (px)\",\"TYPE\":\"float\",\"MIN\":4,\"MAX\":80,\"DEFAULT\":14},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":0.5,\"DEFAULT\":0.18},\n{\"NAME\":\"speed\",\"LABEL\":\"Twinkle speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":2,\"DEFAULT\":0.4}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 p = isf_FragNormCoord * RENDERSIZE / cells, c = floor(p), f = fract(p) - 0.5;\n  float h = hash(c);\n  vec2 o = vec2(hash(c + 3.1), hash(c + 7.7)) - 0.5;\n  float d = length(f - o * 0.6);\n  float star = step(1.0 - density, h) * smoothstep(size, size * 0.3, d);\n  float tw = 0.35 + 0.65 * (0.5 + 0.5 * sin(TIME * speed * (1.0 + 2.0 * h) * 3.0 + h * 40.0));\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, star * tw * (0.5 + 0.5 * hash(c + 1.9))), 1.0);\n}\n"}, {"id": "waves", "name": "Slow waves", "code": "/*{\"DESCRIPTION\":\"Soft bands of two colours rolling slowly across\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"lines\",\"flow\",\"bands\",\"sea\",\"two colours\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.35,0.6,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.6,0.95,1,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Waves\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":12,\"DEFAULT\":2},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.2},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":90}]}*/\nvoid main() {\n  vec2 q = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float v = 0.5 + 0.5 * sin((dot(q, vec2(cos(a), sin(a))) * count - TIME * speed) * 6.2831853);\n  v = mix(step(0.5, v), smoothstep(0.0, 1.0, v), softness);\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, v), 1.0);\n}\n"}, {"id": "discodots", "name": "Disco dots", "code": "/*{\"DESCRIPTION\":\"A grid of round dots, each taking a new colour on the beat\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"particles\",\"beat\",\"dots\",\"grid\",\"bpm\",\"disco\"],\"OLM_CLOCKS\":{\"beat\":{\"FROM\":\"bpm\",\"SCALE\":0.016666666666666666,\"WRAP\":1024}},\"INPUTS\":[\n{\"NAME\":\"bpm\",\"LABEL\":\"Tempo (BPM)\",\"TYPE\":\"float\",\"MIN\":30,\"MAX\":200,\"DEFAULT\":120},\n{\"NAME\":\"cells\",\"LABEL\":\"Dot spacing (px)\",\"TYPE\":\"float\",\"MIN\":6,\"MAX\":120,\"DEFAULT\":40},\n{\"NAME\":\"size\",\"LABEL\":\"Dot size\",\"TYPE\":\"float\",\"MIN\":0.1,\"MAX\":0.5,\"DEFAULT\":0.38},\n{\"NAME\":\"decay\",\"LABEL\":\"Fade\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":8,\"DEFAULT\":1},\n{\"NAME\":\"saturation\",\"LABEL\":\"Saturation\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1},\n{\"NAME\":\"beat\",\"TYPE\":\"float\",\"DEFAULT\":0}]}*/\nvec3 hsv(float h, float s, float v) { vec3 p = abs(fract(vec3(h) + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0); return v * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), s); }\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 p = isf_FragNormCoord * RENDERSIZE / cells, c = floor(p);\n  float n = floor(beat), ph = fract(beat);\n  float h = hash(c + n * 1.37);\n  float disc = smoothstep(size, size - 0.06, length(fract(p) - 0.5));\n  float lvl = pow(1.0 - ph, decay) * step(0.25, hash(c * 1.7 + n));\n  gl_FragColor = vec4(hsv(h, saturation, 1.0) * disc * lvl, 1.0);\n}\n"}, {"id": "scanner", "name": "Scanner", "code": "/*{\"DESCRIPTION\":\"Beams sweeping back and forth, like moving heads\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"lines\",\"chase\",\"beams\",\"moving heads\",\"disco\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[0.4,0.7,1,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Beams\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":8,\"DEFAULT\":3},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.005,\"MAX\":0.3,\"DEFAULT\":0.05},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":3,\"DEFAULT\":0.8},\n{\"NAME\":\"spread\",\"LABEL\":\"Spread\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0},\n{\"NAME\":\"rainbow\",\"LABEL\":\"Rainbow\",\"TYPE\":\"bool\",\"DEFAULT\":false}]}*/\nvec3 hsv(float h, float s, float v) { vec3 p = abs(fract(vec3(h) + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0); return v * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), s); }\nvoid main() {\n  vec2 q = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float x = dot(q, vec2(cos(a), sin(a)));\n  vec3 col = vec3(0.0);\n  for (int i = 0; i < 8; i++) {\n    float fi = float(i);\n    if (fi >= count) break;\n    float pos = sin(TIME * speed * 3.1415927 + fi * spread * 6.2831853 / max(count, 1.0)) * 0.6;\n    float b = exp(-pow((x - pos) / width, 2.0));\n    col += (rainbow ? hsv(fi / max(count, 1.0), 1.0, 1.0) : color.rgb) * b;\n  }\n  gl_FragColor = vec4(min(col, 1.0), 1.0);\n}\n"}, {"id": "confetti", "name": "Confetti", "code": "/*{\"DESCRIPTION\":\"Sparks of random colours popping all over\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"particles\",\"flash\",\"sparkle\",\"sparks\",\"dots\",\"disco\",\"colorful\"],\"INPUTS\":[\n{\"NAME\":\"cells\",\"LABEL\":\"Spark size (px)\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":60,\"DEFAULT\":8},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.3},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":6,\"DEFAULT\":2},\n{\"NAME\":\"decay\",\"LABEL\":\"Fade\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":12,\"DEFAULT\":5},\n{\"NAME\":\"saturation\",\"LABEL\":\"Saturation\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1}]}*/\nvec3 hsv(float h, float s, float v) { vec3 p = abs(fract(vec3(h) + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0); return v * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), s); }\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 c = floor(isf_FragNormCoord * RENDERSIZE / cells);\n  float t = TIME * speed + hash(c) * 31.0;\n  float n = floor(t), ph = fract(t);\n  float on = step(1.0 - density, hash(c + n * 2.13));\n  gl_FragColor = vec4(hsv(hash(c * 0.71 + n), saturation, 1.0) * on * pow(1.0 - ph, decay), 1.0);\n}\n"}, {"id": "hits", "name": "Color hits", "code": "/*{\"DESCRIPTION\":\"The whole canvas, or a few segments, flashing a new colour on every beat\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"fill\",\"beat\",\"bpm\",\"segments\",\"disco\",\"colorful\"],\"OLM_CLOCKS\":{\"beat\":{\"FROM\":\"bpm\",\"SCALE\":0.016666666666666666,\"WRAP\":1024}},\"INPUTS\":[\n{\"NAME\":\"bpm\",\"LABEL\":\"Tempo (BPM)\",\"TYPE\":\"float\",\"MIN\":30,\"MAX\":200,\"DEFAULT\":120},\n{\"NAME\":\"segments\",\"LABEL\":\"Segments\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":12,\"DEFAULT\":1},\n{\"NAME\":\"decay\",\"LABEL\":\"Fade\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":12,\"DEFAULT\":4},\n{\"NAME\":\"saturation\",\"LABEL\":\"Saturation\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":1},\n{\"NAME\":\"base\",\"LABEL\":\"Glow between hits\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0},\n{\"NAME\":\"beat\",\"TYPE\":\"float\",\"DEFAULT\":0}]}*/\nvec3 hsv(float h, float s, float v) { vec3 p = abs(fract(vec3(h) + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0); return v * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), s); }\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 q = isf_FragNormCoord - 0.5;\n  float a = radians(angle);\n  vec2 d = vec2(cos(a), sin(a));\n  float x = dot(q, d) / (0.5 * (abs(d.x) + abs(d.y))) * 0.5 + 0.5;   // 0 to 1 across the canvas, at any angle\n  float seg = floor(clamp(x, 0.0, 0.9999) * floor(segments));\n  float n = floor(beat), ph = fract(beat);\n  float h = hash(vec2(seg * 7.13 + 1.7, n * 3.71 + 0.3));\n  gl_FragColor = vec4(hsv(h, saturation, 1.0) * mix(base, 1.0, pow(1.0 - ph, decay)), 1.0);\n}\n"}, {"id": "mirrorball", "name": "Mirror ball", "code": "/*{\"DESCRIPTION\":\"Spots of light sweeping round, like a mirror ball\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"particles\",\"flow\",\"dots\",\"spots\",\"rotate\",\"disco\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.95,0.9,1]},\n{\"NAME\":\"cells\",\"LABEL\":\"Spot spacing (px)\",\"TYPE\":\"float\",\"MIN\":6,\"MAX\":100,\"DEFAULT\":28},\n{\"NAME\":\"size\",\"LABEL\":\"Spot size\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":0.5,\"DEFAULT\":0.18},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.6},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":2,\"DEFAULT\":0.25},\n{\"NAME\":\"centerX\",\"LABEL\":\"Center X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Center Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 q = (isf_FragNormCoord - vec2(centerX, centerY)) * RENDERSIZE;\n  float r = length(q), a = atan(q.y, q.x) + TIME * speed;\n  float ring = floor(r / cells);\n  float per = max(6.0, floor(6.2831853 * (ring + 0.5)));\n  vec2 c = vec2(ring, floor(a / 6.2831853 * per));\n  vec2 f = vec2(fract(r / cells), fract(a / 6.2831853 * per)) - 0.5;\n  float spot = step(1.0 - density, hash(c)) * smoothstep(size, size * 0.4, length(f));\n  gl_FragColor = vec4(color.rgb * spot * (0.6 + 0.4 * hash(c + 4.0)), 1.0);\n}\n"}, {"id": "equalizer", "name": "Equalizer", "code": "/*{\"DESCRIPTION\":\"Bars bouncing like a music equalizer, green to red\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\",\"show\",\"lines\",\"flow\",\"bars\",\"music\",\"vu\",\"disco\"],\"INPUTS\":[\n{\"NAME\":\"count\",\"LABEL\":\"Bars\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":48,\"DEFAULT\":12},\n{\"NAME\":\"gap\",\"LABEL\":\"Gap\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":0.8,\"DEFAULT\":0.2},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":4,\"DEFAULT\":1.2},\n{\"NAME\":\"level\",\"LABEL\":\"Level\",\"TYPE\":\"float\",\"MIN\":0.1,\"MAX\":1,\"DEFAULT\":0.7},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y); }\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + vec2(17.0, 9.0); a *= 0.5; } return v; }\nvoid main() {\n  vec2 q = isf_FragNormCoord - 0.5;\n  float a = radians(angle);\n  vec2 r = vec2(dot(q, vec2(cos(a), sin(a))), dot(q, vec2(-sin(a), cos(a)))) + 0.5;\n  float i = floor(r.x * count);\n  float hgt = clamp(level * (0.25 + 1.1 * vnoise(vec2(i * 3.7, TIME * speed))), 0.0, 1.0);\n  float on = step(r.y, hgt) * step(gap * 0.5, fract(r.x * count)) * step(fract(r.x * count), 1.0 - gap * 0.5);\n  vec3 col = mix(vec3(0.1, 1.0, 0.2), vec3(1.0, 0.85, 0.0), smoothstep(0.45, 0.7, r.y));\n  col = mix(col, vec3(1.0, 0.1, 0.05), smoothstep(0.75, 0.9, r.y));\n  gl_FragColor = vec4(col * on, 1.0);\n}\n"}, {"id": "gradient", "name": "Gradient", "code": "/*{\"DESCRIPTION\":\"Two-color gradient, optionally scrolling\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"gradient\",\"still\",\"two colours\",\"scroll\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1,0.1,0.4,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.1,0.4,1,1]},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0},\n{\"NAME\":\"speed\",\"LABEL\":\"Scroll\",\"TYPE\":\"float\",\"MIN\":-2,\"MAX\":2,\"DEFAULT\":0},\n{\"NAME\":\"mirror\",\"LABEL\":\"Mirror\",\"TYPE\":\"bool\",\"DEFAULT\":true}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float x = dot(p, vec2(cos(a), sin(a))) + 0.5 - TIME * speed;\n  float t = mirror ? 1.0 - abs(fract(x * 0.5) * 2.0 - 1.0) : fract(x);\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, t), 1.0);\n}\n"}, {"id": "shape", "name": "Shape mask", "code": "/*{\"DESCRIPTION\":\"A circle, ring, rectangle or band. White on black: put it on a layer set to Multiply to show the layers below only inside the shape\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"utility\",\"geometric\",\"still\",\"mask\",\"circle\",\"ring\",\"rectangle\"],\"INPUTS\":[\n{\"NAME\":\"shape\",\"LABEL\":\"Shape\",\"TYPE\":\"long\",\"VALUES\":[0,1,2,3],\"LABELS\":[\"Circle\",\"Ring\",\"Rectangle\",\"Band\"],\"DEFAULT\":0},\n{\"NAME\":\"color\",\"LABEL\":\"Inside\",\"TYPE\":\"color\",\"DEFAULT\":[1,1,1,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Outside\",\"TYPE\":\"color\",\"DEFAULT\":[0,0,0,1]},\n{\"NAME\":\"invert\",\"LABEL\":\"Invert\",\"TYPE\":\"bool\",\"DEFAULT\":false},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":2,\"DEFAULT\":0.6},\n{\"NAME\":\"thickness\",\"LABEL\":\"Thickness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.1},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0},\n{\"NAME\":\"centerX\",\"LABEL\":\"Centre X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Centre Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nvoid main() {\n  vec2 q = (isf_FragNormCoord - vec2(centerX, 1.0 - centerY)) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  q = vec2(q.x * cos(a) + q.y * sin(a), q.y * cos(a) - q.x * sin(a));\n  float d;\n  if (shape == 0) d = length(q) - size * 0.5;\n  else if (shape == 1) d = abs(length(q) - size * 0.5) - thickness * 0.5;\n  else if (shape == 2) { vec2 e = abs(q) - vec2(size, thickness * 2.0) * 0.5; d = length(max(e, 0.0)) + min(max(e.x, e.y), 0.0); }\n  else d = abs(q.y) - thickness * 0.5;\n  float s = softness * 0.2 + 0.002;\n  float m = 1.0 - smoothstep(-s, s, d);\n  if (invert) m = 1.0 - m;\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, m), 1.0);\n}\n"}, {"id": "solid", "name": "Solid color", "code": "/*{\"DESCRIPTION\":\"Solid color\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\",\"architectural\",\"fill\",\"still\",\"plain\",\"one colour\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[1,1,1,1]}]}*/\nvoid main() { gl_FragColor = vec4(color.rgb, 1.0); }\n"}, {"id": "wash", "name": "Color wash", "code": "/*{\"DESCRIPTION\":\"The whole surface fades slowly between two colours, or the fade travels across it\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"architectural\", \"fill\", \"drift\", \"facade\", \"two colours\", \"slow\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.95,0.55,0.2,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.15,0.3,0.9,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"spread\",\"LABEL\":\"Spread\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":2,\"DEFAULT\":0.5},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  float x = dot(p, vec2(cos(a), sin(a)));\n  float m = 0.5 + 0.5 * sin(6.2831853 * (TIME * speed * 0.2 - x * spread * 0.5));\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 1.0, m)), 1.0);\n}\n"}, {"id": "cascade", "name": "Cascade", "code": "/*{\"DESCRIPTION\":\"Columns light up one after another, softly, like a wave along a facade\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"architectural\", \"lines\", \"flow\", \"columns\", \"sequence\", \"facade\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Off\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"On\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.82,0.55,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Columns\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":32,\"DEFAULT\":8},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":1,\"DEFAULT\":0.75},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"tail\",\"LABEL\":\"Length\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":1,\"DEFAULT\":0.6},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.3},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle), asp = RENDERSIZE.x / RENDERSIZE.y;\n  float e = 0.5 * (abs(cos(a)) * asp + abs(sin(a)));\n  float x = clamp(dot(p, vec2(cos(a), sin(a))) / (2.0 * e) + 0.5, 0.0, 0.9999) * count;\n  float i = floor(x), s = softness * 0.5 + 0.01;\n  float shape = 1.0 - smoothstep(width - s, width + s, abs(fract(x) - 0.5) * 2.0);\n  float level = pow(0.5 + 0.5 * cos(6.2831853 * (i / count - TIME * speed * 0.5)), 1.0 + 12.0 * (1.0 - tail));\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, shape * level), 1.0);\n}\n"}, {"id": "orbit", "name": "Orbit", "code": "/*{\"DESCRIPTION\":\"A soft two-colour gradient turning slowly around the middle\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"architectural\", \"gradient\", \"drift\", \"rotate\", \"two colours\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.05,0.2,0.75,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.9,0.35,0.6,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.8},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle) + TIME * speed * 0.8;\n  float x = dot(p, vec2(cos(a), sin(a)));\n  float w = mix(0.02, 1.4, softness);\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, smoothstep(-w * 0.5, w * 0.5, x)), 1.0);\n}\n"}, {"id": "marble", "name": "Marble", "code": "/*{\"DESCRIPTION\":\"Slow veins of light flowing through a stone-like surface\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"architectural\", \"organic\", \"drift\", \"stone\", \"veins\", \"luxury\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Stone\",\"TYPE\":\"color\",\"DEFAULT\":[0.04,0.05,0.1,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Veins\",\"TYPE\":\"color\",\"DEFAULT\":[0.95,0.78,0.5,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.12},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":8,\"DEFAULT\":2.5},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.45}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y); }\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + vec2(17.0, 9.0); a *= 0.5; } return v; }\n\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed * 0.5;\n  vec2 q = p * scale;\n  float n = fbm(q * 0.6 + vec2(t * 0.3, -t * 0.2));\n  float v = abs(sin(q.x * 0.9 + q.y * 0.6 + n * 6.0 + t * 0.4));\n  float m = pow(1.0 - v, mix(14.0, 2.0, softness)) + 0.25 * smoothstep(0.45, 0.8, n);\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, clamp(m, 0.0, 1.0)), 1.0);\n}\n"}, {"id": "embers", "name": "Embers", "code": "/*{\"DESCRIPTION\":\"A warm glow that breathes and flickers like embers, for warm, calm light\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"architectural\", \"organic\", \"drift\", \"warm\", \"fire\", \"candle\", \"hospitality\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Dark\",\"TYPE\":\"color\",\"DEFAULT\":[0.12,0.015,0.0,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Glow\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.5,0.12,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.3},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":10,\"DEFAULT\":3},\n{\"NAME\":\"flicker\",\"LABEL\":\"Flicker\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y); }\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + vec2(17.0, 9.0); a *= 0.5; } return v; }\n\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed;\n  vec2 q = p * scale;\n  float n = fbm(q + vec2(t * 0.15, -t * 0.4));\n  float f = mix(1.0, 0.55 + 0.9 * vnoise(q * 0.7 + vec2(t * 4.0, 3.0)), flicker);\n  float m = smoothstep(0.28, 0.8, n) * f;\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, clamp(m, 0.0, 1.0)), 1.0);\n}\n"}, {"id": "nebula", "name": "Nebula", "code": "/*{\"DESCRIPTION\":\"Two coloured clouds of light slowly swirling through each other in the dark\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"ambient\", \"organic\", \"drift\", \"space\", \"clouds\", \"two colours\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.55,0.1,0.9,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.75,0.9,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.2},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":6,\"DEFAULT\":1.8},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.65}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y); }\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + vec2(17.0, 9.0); a *= 0.5; } return v; }\n\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed * 0.4;\n  vec2 q = p * scale;\n  vec2 w = vec2(fbm(q + vec2(t, 1.7)), fbm(q + vec2(5.2, -t)));\n  float f1 = fbm(q + 1.6 * w + vec2(t * 0.3, 0.0)), f2 = fbm(q * 1.3 + 1.2 * w.yx + vec2(7.0, -t * 0.4));\n  float lo = mix(0.6, 0.15, density);\n  vec3 col = colorA.rgb * smoothstep(lo, lo + 0.4, f1) + colorB.rgb * smoothstep(lo + 0.05, lo + 0.45, f2);\n  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);\n}\n"}, {"id": "caustics", "name": "Caustics", "code": "/*{\"DESCRIPTION\":\"The moving net of light at the bottom of a pool\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"ambient\", \"organic\", \"flow\", \"water\", \"pool\", \"sea\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Water\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.18,0.32,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Light\",\"TYPE\":\"color\",\"DEFAULT\":[0.75,0.97,1.0,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.35},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":10,\"DEFAULT\":4},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.4}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed * 1.2;\n  vec2 q = p * scale;\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    q += 0.55 * vec2(sin(q.y * 1.3 + t * 0.9 + fk * 1.7), cos(q.x * 1.1 - t * 0.7 + fk * 2.3));\n  }\n  float w = 1.0 - abs(sin(q.x) * sin(q.y));\n  float m = pow(w, mix(24.0, 5.0, softness));\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, m), 1.0);\n}\n"}, {"id": "fireflies", "name": "Fireflies", "code": "/*{\"DESCRIPTION\":\"Soft points of light wandering and glowing in the dark\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"ambient\", \"particles\", \"drift\", \"night\", \"garden\", \"glow\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.8,0.3,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.02,1]},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.75},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.2,\"MAX\":3,\"DEFAULT\":1},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":16,\"DEFAULT\":5},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.3}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed * 1.5;\n  vec2 g = p * scale, id = floor(g);\n  float glow = 0.0;\n  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {\n    vec2 cid = id + vec2(float(x), float(y));\n    float h1 = hash(cid), h2 = hash(cid + 3.1), h3 = hash(cid + 7.7);\n    if (h3 > density) continue;\n    vec2 pos = cid + 0.5 + 0.42 * vec2(sin(t * (0.6 + h1) + h2 * 6.28), cos(t * (0.5 + h2) + h1 * 6.28));\n    float r = 0.12 * size, d = length(g - pos);\n    glow += exp(-d * d / (r * r)) * (0.55 + 0.45 * sin(t * 2.0 + h1 * 6.28));\n  }\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, clamp(glow, 0.0, 1.0)), 1.0);\n}\n"}, {"id": "bokeh", "name": "Bokeh", "code": "/*{\"DESCRIPTION\":\"Soft out-of-focus circles of two colours drifting upwards\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"ambient\", \"particles\", \"drift\", \"lights\", \"dreamy\", \"two colours\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.6,0.2,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.3,0.5,1.0,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.2,\"MAX\":2,\"DEFAULT\":1},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.6},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.2}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed;\n  vec3 col = background.rgb;\n  for (int l = 0; l < 3; l++) {\n    float fl = float(l), s = 2.5 + fl * 1.8;\n    vec2 g = p * s + vec2(fl * 3.3, t * (0.35 + fl * 0.15)), id = floor(g), f = fract(g);\n    float h = hash(id + fl * 11.0);\n    if (h > density) continue;\n    vec2 pos = 0.5 + 0.3 * vec2(hash(id + 1.3 + fl) - 0.5, hash(id + 2.9 + fl) - 0.5);\n    float r = min(0.48, (0.18 + 0.2 * hash(id + 4.1)) * size);\n    float d = length(f - pos);\n    float m = 1.0 - smoothstep(r * (1.0 - softness * 0.7) - 0.01, r, d);\n    col += mix(colorA.rgb, colorB.rgb, hash(id + 6.7)) * m * (0.35 + 0.15 * fl);\n  }\n  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);\n}\n"}, {"id": "kaleido", "name": "Kaleidoscope", "code": "/*{\"DESCRIPTION\":\"A turning kaleidoscope of mirrored patterns\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\", \"show\", \"geometric\", \"flow\", \"mirror\", \"psychedelic\", \"disco\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.0,0.6,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.8,1.0,1]},\n{\"NAME\":\"rainbow\",\"LABEL\":\"Rainbow\",\"TYPE\":\"bool\",\"DEFAULT\":false},\n{\"NAME\":\"count\",\"LABEL\":\"Mirrors\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":16,\"DEFAULT\":6},\n{\"NAME\":\"scale\",\"LABEL\":\"Scale\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":8,\"DEFAULT\":3},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.2}]}*/\nvec3 hsv(float h) { return clamp(abs(fract(h + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0); }\n\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed * 1.5;\n  float seg = 6.2831853 / floor(count), a = mod(atan(p.y, p.x) + t * 0.3, seg), r = length(p);\n  a = abs(a - seg * 0.5);\n  vec2 k = r * vec2(cos(a), sin(a)) * scale * 6.0;\n  float v = sin(k.x + t * 2.0) * sin(k.y - t * 1.3) + 0.5 * sin(r * scale * 8.0 - t * 3.0);\n  float m = smoothstep(-0.05 - softness * 0.6, 0.05 + softness * 0.6, v);\n  vec3 col = rainbow ? hsv(r * 0.8 - t * 0.15 + m * 0.35) * m : mix(colorA.rgb, colorB.rgb, m);\n  gl_FragColor = vec4(col, 1.0);\n}\n"}, {"id": "lasers", "name": "Laser fan", "code": "/*{\"DESCRIPTION\":\"Thin beams fanning out from a point and sweeping from side to side\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\", \"show\", \"lines\", \"chase\", \"beams\", \"disco\", \"club\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[0.1,1.0,0.35,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Beams\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":24,\"DEFAULT\":8},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.001,\"MAX\":0.05,\"DEFAULT\":0.008},\n{\"NAME\":\"spread\",\"LABEL\":\"Spread\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":180,\"DEFAULT\":80},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"centerX\",\"LABEL\":\"Center X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Center Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.0}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 c = (vec2(centerX, centerY) - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 d = p - c;\n  float sway = sin(TIME * speed * 2.0) * radians(spread) * 0.35, m = 0.0;\n  for (int i = 0; i < 24; i++) {\n    if (float(i) >= count) break;\n    float f = count > 1.0 ? float(i) / (count - 1.0) - 0.5 : 0.0;\n    float a = radians(90.0) + f * radians(spread) + sway;\n    vec2 dir = vec2(cos(a), sin(a));\n    float along = dot(d, dir), off = abs(d.x * dir.y - d.y * dir.x);\n    m += step(0.0, along) * exp(-off * off / (width * width)) * exp(-along * 0.6);\n  }\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, clamp(m, 0.0, 1.0)), 1.0);\n}\n"}, {"id": "tunnel", "name": "Tunnel", "code": "/*{\"DESCRIPTION\":\"Rings rushing out of a point, as in a tunnel (in reverse they rush in)\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\", \"show\", \"radial\", \"flow\", \"rings\", \"tunnel\", \"disco\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.03,0.0,0.1,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Rings\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.2,0.8,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Rings\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":30,\"DEFAULT\":10},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.3},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerX\",\"LABEL\":\"Center X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Center Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 c = (vec2(centerX, centerY) - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float d = length(p - c);\n  float x = count * 0.12 / (d + 0.03) - TIME * speed * 3.0;\n  float s = softness * 0.5 + 0.01;\n  float m = (1.0 - smoothstep(width - s, width + s, abs(fract(x) - 0.5) * 2.0)) * smoothstep(0.04, 0.3, d);\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, m), 1.0);\n}\n"}, {"id": "chevrons", "name": "Chevrons", "code": "/*{\"DESCRIPTION\":\"V shapes marching across, in two colours\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\", \"show\", \"lines\", \"chase\", \"arrows\", \"stripes\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.15,0.2,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Chevrons\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":16,\"DEFAULT\":4},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.05,\"MAX\":1,\"DEFAULT\":0.45},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle);\n  vec2 dir = vec2(cos(a), sin(a));\n  float x = dot(p, dir) + abs(p.x * dir.y - p.y * dir.x) * 0.8;\n  float s = softness * 0.5 + 0.01;\n  float m = 1.0 - smoothstep(width - s, width + s, abs(fract(x * count - TIME * speed * 2.0) - 0.5) * 2.0);\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, m), 1.0);\n}\n"}, {"id": "lightning", "name": "Lightning", "code": "/*{\"DESCRIPTION\":\"Bolts and flashes of light at random moments\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\", \"show\", \"lines\", \"flash\", \"storm\", \"strobe\", \"thunder\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[0.75,0.8,1.0,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.01,0.0,0.04,1]},\n{\"NAME\":\"density\",\"LABEL\":\"How often\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.35},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.002,\"MAX\":0.05,\"DEFAULT\":0.012},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y); }\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + vec2(17.0, 9.0); a *= 0.5; } return v; }\n\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed * 4.0 + 0.45, n = floor(t), ph = fract(t), asp = RENDERSIZE.x / RENDERSIZE.y;\n  // which moments flash, where and how bright: evenly spread sequences, the same on every GPU\n  float on = step(1.0 - density, fract(n * 0.618034 + 0.12));\n  float x0 = (fract(n * 0.754878 + 0.3) - 0.5) * asp * 0.85;\n  float xj = x0 + (vnoise(vec2(p.y * 6.0, n)) - 0.5) * 0.3 + (vnoise(vec2(p.y * 22.0, n + 5.0)) - 0.5) * 0.07;\n  float dx = abs(p.x - xj);\n  float bolt = exp(-dx * dx / (width * width)) * exp(-ph * 5.0);\n  float flash = exp(-ph * 7.0) * (0.25 + 0.3 * fract(n * 0.569840 + 0.5));\n  gl_FragColor = vec4(clamp(background.rgb + color.rgb * on * (bolt + flash), 0.0, 1.0), 1.0);\n}\n"}, {"id": "heartbeat", "name": "Heartbeat", "code": "/*{\"DESCRIPTION\":\"A double pulse of light from the middle, like a heartbeat\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"party\", \"show\", \"radial\", \"beat\", \"pulse\", \"heart\", \"rhythm\"],\"INPUTS\":[\n{\"NAME\":\"color\",\"LABEL\":\"Color\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.0,0.15,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.1,\"MAX\":2,\"DEFAULT\":0.8},\n{\"NAME\":\"decay\",\"LABEL\":\"Fade\",\"TYPE\":\"float\",\"MIN\":0.5,\"MAX\":4,\"DEFAULT\":1.5},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.4},\n{\"NAME\":\"centerX\",\"LABEL\":\"Center X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Center Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 c = (vec2(centerX, centerY) - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float ph = fract(TIME * speed * 1.5 + 0.27), k = decay * 5.0;\n  float e = exp(-ph * k) + 0.75 * step(0.2, ph) * exp(-(ph - 0.2) * k);\n  float d = length(p - c), r = size * (0.35 + 0.25 * e);\n  float m = e * exp(-d * d / (r * r));\n  gl_FragColor = vec4(mix(background.rgb, color.rgb, clamp(m, 0.0, 1.0)), 1.0);\n}\n"}, {"id": "ganzfeld", "name": "Turel", "code": "/*{\"DESCRIPTION\":\"A field of colour with a glowing opening in it; the two slowly trade colours, so the eye loses its depth\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"architectural\", \"fill\", \"drift\", \"perception\", \"aperture\", \"light art\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Field\",\"TYPE\":\"color\",\"DEFAULT\":[0.12,0.2,0.75,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Opening\",\"TYPE\":\"color\",\"DEFAULT\":[0.95,0.45,0.35,1]},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.15},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.1,\"MAX\":1,\"DEFAULT\":0.55},\n{\"NAME\":\"softness\",\"LABEL\":\"Softness\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.35}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float asp = RENDERSIZE.x / RENDERSIZE.y, s = 0.5 + 0.5 * sin(TIME * speed * 0.6);\n  vec2 q = abs(p) - vec2(size * 0.42 * asp, size * 0.42);\n  float d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);\n  float m = 1.0 - smoothstep(-0.005 - softness * 0.12, 0.005 + softness * 0.12, d);\n  // the opening: the other colour, and always a little brighter than the field, as light from beyond it\n  vec3 field = mix(colorA.rgb, colorB.rgb, s) * (0.7 + 0.2 * (1.0 - length(p)));\n  vec3 open = mix(mix(colorB.rgb, colorA.rgb, s), vec3(1.0), 0.18);\n  float halo = exp(-max(d, 0.0) * 18.0) * 0.25;\n  gl_FragColor = vec4(clamp(mix(field + open * halo, open, m), 0.0, 1.0), 1.0);\n}\n"}, {"id": "infinity", "name": "Kusuma", "code": "/*{\"DESCRIPTION\":\"Points of light in rows that go on forever, as between two mirrors, glowing on and off\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"ambient\", \"particles\", \"drift\", \"mirror\", \"dots\", \"light art\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.85,0.5,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.9,0.3,0.7,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Lights\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":20,\"DEFAULT\":7},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.2,\"MAX\":2,\"DEFAULT\":1.4},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.25}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed;\n  vec3 col = background.rgb;\n  for (int l = 0; l < 5; l++) {\n    float fl = float(l), k = pow(1.6, fl), fade = pow(0.62, fl);\n    vec2 g = p * count * k + vec2(fl * 0.37, fl * 0.71), id = floor(g), f = fract(g) - 0.5;\n    float h = hash(id + fl * 13.0);\n    float on = 0.5 + 0.5 * sin(t * (1.5 + h * 2.0) + h * 6.2831853);\n    float r = 0.18 * size, d = length(f);\n    col += mix(colorA.rgb, colorB.rgb, step(0.6, hash(id + 3.3 + fl))) * exp(-d * d / (r * r * 0.25)) * on * fade;\n  }\n  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);\n}\n"}, {"id": "sunhaze", "name": "Elisun", "code": "/*{\"DESCRIPTION\":\"A huge low sun glowing through a slowly moving mist\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"ambient\", \"radial\", \"drift\", \"sun\", \"mist\", \"light art\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Sun\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.62,0.18,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Haze\",\"TYPE\":\"color\",\"DEFAULT\":[0.35,0.16,0.06,1]},\n{\"NAME\":\"size\",\"LABEL\":\"Size\",\"TYPE\":\"float\",\"MIN\":0.1,\"MAX\":1.5,\"DEFAULT\":0.55},\n{\"NAME\":\"density\",\"LABEL\":\"Haze\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.2},\n{\"NAME\":\"centerX\",\"LABEL\":\"Center X\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"centerY\",\"LABEL\":\"Center Y\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.55}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nfloat vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y); }\nfloat fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + vec2(17.0, 9.0); a *= 0.5; } return v; }\n\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  vec2 c = (vec2(centerX, centerY) - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed * 0.4, d = length(p - c), r = size * 0.4;\n  float disc = 1.0 - smoothstep(r * 0.97, r * 1.02, d);\n  float glow = exp(-max(d - r, 0.0) * 3.5);\n  float mist = fbm(p * 3.0 + vec2(t, t * 0.3));\n  vec3 col = mix(colorB.rgb * (0.35 + 0.65 * glow), colorA.rgb, clamp(disc + 0.45 * glow, 0.0, 1.0));\n  col = mix(col, colorB.rgb * (0.6 + 0.8 * mist), density * 0.55 * (1.0 - disc * 0.6));\n  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);\n}\n"}, {"id": "tubes", "name": "Flavine", "code": "/*{\"DESCRIPTION\":\"Coloured tubes of light on a wall, each washing the wall around it in its colour\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"architectural\", \"lines\", \"drift\", \"tubes\", \"minimal\", \"light art\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,0.2,0.45,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.3,0.55,1.0,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Wall\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Tubes\",\"TYPE\":\"float\",\"MIN\":1,\"MAX\":12,\"DEFAULT\":4},\n{\"NAME\":\"width\",\"LABEL\":\"Width\",\"TYPE\":\"float\",\"MIN\":0.005,\"MAX\":0.1,\"DEFAULT\":0.02},\n{\"NAME\":\"softness\",\"LABEL\":\"Glow\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.6},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.1},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":0}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle), asp = RENDERSIZE.x / RENDERSIZE.y;\n  float e = 0.5 * (abs(cos(a)) * asp + abs(sin(a)));\n  float x = (dot(p, vec2(cos(a), sin(a))) / (2.0 * e) + 0.5) * count;\n  float i = floor(x), dx = abs(fract(x) - 0.5) / count * 2.0 * e;\n  float s = 0.5 + 0.5 * sin(TIME * speed * 1.5 + i * 2.1);\n  vec3 tube = mix(colorA.rgb, colorB.rgb, mod(i, 2.0) < 1.0 ? s : 1.0 - s);\n  float core = 1.0 - smoothstep(width * 0.5, width * 0.5 + 0.002, dx);\n  float glow = exp(-dx / (0.02 + softness * 0.25)) * 0.8;\n  gl_FragColor = vec4(clamp(background.rgb + tube * max(core, glow), 0.0, 1.0), 1.0);\n}\n"}, {"id": "opwave", "name": "Rilay", "code": "/*{\"DESCRIPTION\":\"Bands that ripple and bend so the surface seems to move by itself\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"lively\", \"show\", \"lines\", \"flow\", \"optical\", \"stripes\", \"black and white\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.0,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[1.0,1.0,1.0,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Bands\",\"TYPE\":\"float\",\"MIN\":2,\"MAX\":60,\"DEFAULT\":18},\n{\"NAME\":\"size\",\"LABEL\":\"Bend\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.5},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.3},\n{\"NAME\":\"angle\",\"LABEL\":\"Angle\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":360,\"DEFAULT\":90}]}*/\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float a = radians(angle), t = TIME * speed * 1.5;\n  float x = dot(p, vec2(cos(a), sin(a))), y = dot(p, vec2(-sin(a), cos(a)));\n  float bend = size * 0.12 * sin(y * 7.0 + t) * (0.6 + 0.4 * sin(x * 3.0 - t * 0.7));\n  float m = smoothstep(-0.08, 0.08, sin((x + bend) * count * 3.1415927));\n  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, m), 1.0);\n}\n"}, {"id": "constellation", "name": "Villaray", "code": "/*{\"DESCRIPTION\":\"Countless small lights that swell and fade in slow waves crossing them\",\"CREDIT\":\"nouPix\",\"CATEGORIES\":[\"calm\", \"ambient\", \"particles\", \"flow\", \"stars\", \"pixels\", \"light art\"],\"INPUTS\":[\n{\"NAME\":\"colorA\",\"LABEL\":\"Color A\",\"TYPE\":\"color\",\"DEFAULT\":[0.9,0.95,1.0,1]},\n{\"NAME\":\"colorB\",\"LABEL\":\"Color B\",\"TYPE\":\"color\",\"DEFAULT\":[0.3,0.6,1.0,1]},\n{\"NAME\":\"background\",\"LABEL\":\"Background\",\"TYPE\":\"color\",\"DEFAULT\":[0.0,0.0,0.02,1]},\n{\"NAME\":\"count\",\"LABEL\":\"Lights\",\"TYPE\":\"float\",\"MIN\":10,\"MAX\":80,\"DEFAULT\":32},\n{\"NAME\":\"density\",\"LABEL\":\"Density\",\"TYPE\":\"float\",\"MIN\":0,\"MAX\":1,\"DEFAULT\":0.75},\n{\"NAME\":\"scale\",\"LABEL\":\"Waves\",\"TYPE\":\"float\",\"MIN\":0.2,\"MAX\":4,\"DEFAULT\":1.2},\n{\"NAME\":\"speed\",\"LABEL\":\"Speed\",\"TYPE\":\"float\",\"MIN\":-1,\"MAX\":1,\"DEFAULT\":0.3}]}*/\nfloat hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }\nvoid main() {\n  vec2 p = (isf_FragNormCoord - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0);\n  float t = TIME * speed;\n  vec2 g = p * count, id = floor(g), f = fract(g) - 0.5;\n  float h = hash(id);\n  vec2 off = (vec2(hash(id + 1.7), hash(id + 2.9)) - 0.5) * 0.6;\n  float d = length(f - off);\n  float wave = 0.5 + 0.5 * sin((p.x * 0.8 + p.y * 0.5) * scale * 6.2831853 - t * 2.0 + sin(p.y * 3.0 + t) * 0.6);\n  float lit = step(1.0 - density, h) * (0.15 + 0.85 * pow(wave, 2.0)) * (0.7 + 0.3 * sin(t * 4.0 + h * 40.0));\n  float m = exp(-d * d / 0.03) * lit;\n  gl_FragColor = vec4(clamp(background.rgb + mix(colorA.rgb, colorB.rgb, hash(id + 5.5)) * m, 0.0, 1.0), 1.0);\n}\n"}];
